const R = (x, n) => { const f = Math.pow(10, n || 0); return Math.round(x * f) / f; };

// INICIALIZAR CONTEXTO
// Crea el estado inicial SOLO si no existe (asi se conserva lo guardado en disco al reiniciar).
// Con msg.payload.reset = true borra todo y vuelve a empezar.
const force = !!(msg.payload && msg.payload.reset === true);
if (force || !G('b02_state')) {
  S('b02_state', {
    volume: 800, level: 40, setpoint: 65, main: 1,
    pumps: { 1: { enabled: true, fault: false, run: false }, 2: { enabled: true, fault: false, run: false } },
    demandBase: 50, demandFactor: 1, leakLpm: 0, valveClosed: false,
    flowIn: 0, flowOut: 0, demand: 0, leak: 0, pressure: 1.6, power: 0.05, dry: false,
    t: 0, last: Date.now()
  });
  S('b02_kpi', { pumpedL: 0, leakedL: 0, energyKWh: 0, pumpSec: 0, totalSec: 0,
    out: { volumen_bombeado_m3: 0, energia_kwh: 0, tiempo_activo_pct: 0, error_nivel_pct: 0, eficiencia_volumetrica_pct: 100 } });
  S('b02_history', { t: [], nivel: [], presion: [], caudal: [], potencia: [], last: 0 });
  S('b02_alarms', []);
  S('b02_audit', []);
  node.status({ fill: 'green', shape: 'dot', text: force ? 'Reinicio manual hecho' : 'Contexto creado' });
  msg.payload = force ? 'Simulacion reiniciada (todo borrado)' : 'Contexto inicializado';
} else {
  node.status({ fill: 'blue', shape: 'ring', text: 'Contexto restaurado de disco' });
  msg.payload = 'Estado restaurado desde el contexto file-backed';
}
return msg;

// ---- Utilidades comunes: contexto GLOBAL file-backed (con respaldo en memoria) ----
const ST = 'file';
const G = k => { try { return global.get(k, ST); } catch (e) { return global.get(k); } };
const S = (k, v) => { try { global.set(k, v, ST); } catch (e) { global.set(k, v); } };
const R = (x, n) => { const f = Math.pow(10, n || 0); return Math.round(x * f) / f; };

// SIMULADOR (se ejecuta cada 1 s)
// 1) Control automatico de bombas con histeresis  2) Balance de masa  3) Presion y potencia
const s = G('b02_state');
if (!s) { node.status({ fill: 'red', shape: 'ring', text: 'Sin estado: ejecuta Inicializar' }); return null; }

const CAP = 2000;   // capacidad del tanque (L)
const QP = 80;      // caudal nominal de cada bomba (L/min)
const now = Date.now();
let dt = (now - (s.last || now)) / 1000;   // paso real en segundos
if (!(dt > 0)) dt = 1;
if (dt > 5) dt = 5;
s.last = now;
s.t = (s.t || 0) + dt;

// ---------- 1) CONTROL AUTOMATICO ----------
const av = id => s.pumps[id].enabled && !s.pumps[id].fault;   // bomba disponible
const otro = id => (id === 1 ? 2 : 1);
let prim = null, sec = null;   // bomba principal efectiva y de apoyo
if (av(s.main)) { prim = s.main; if (av(otro(s.main))) sec = otro(s.main); }
else if (av(otro(s.main))) { prim = otro(s.main); }
[1, 2].forEach(id => { if (!av(id)) s.pumps[id].run = false; });
if (prim) {   // principal: arranca bajo SP-3, para al llegar a SP
  const p = s.pumps[prim];
  if (s.level < s.setpoint - 3) p.run = true; else if (s.level >= s.setpoint) p.run = false;
}
if (sec) {    // apoyo: arranca bajo SP-12, para sobre SP-6
  const p = s.pumps[sec];
  if (s.level < s.setpoint - 12) p.run = true; else if (s.level >= s.setpoint - 6) p.run = false;
}
const nRun = (s.pumps[1].run ? 1 : 0) + (s.pumps[2].run ? 1 : 0);

// ---------- 2) BALANCE DE MASA ----------
// dV/dt = Qentrada - Qsalida     (Qsalida = consumo + fuga)
const flowIn = nRun * QP * (1 + (Math.random() - 0.5) * 0.02);                       // ruido +-1%
const base = s.demandBase + 15 * Math.sin(2 * Math.PI * s.t / 300) + (Math.random() - 0.5) * 4;
const factor = s.valveClosed ? 0.1 : s.demandFactor;
const demand = Math.max(0, base * factor);                                           // consumo (L/min)
const leak = (s.leakLpm > 0 && s.volume > 0) ? s.leakLpm * (0.5 + 0.5 * s.level / 100) : 0;
const want = demand + leak;
const maxOut = flowIn + s.volume / (dt / 60);   // no se puede sacar mas agua de la que hay
const ratio = want > maxOut ? maxOut / want : 1;
const outD = demand * ratio, outL = leak * ratio;
const flowOut = outD + outL;
let vol = s.volume + (flowIn - flowOut) * dt / 60;
if (vol > CAP) vol = CAP;
if (vol < 0) vol = 0;
const level = vol / CAP * 100;

// ---------- 3) PRESION Y POTENCIA ----------
const dry = nRun > 0 && vol <= 20;                         // bombas activas sin agua
const surplus = Math.max(0, flowIn - flowOut);
let P = 1.0 + 0.015 * level + nRun * 1.0 + 0.007 * surplus - 0.002 * flowOut + (Math.random() - 0.5) * 0.08;
if (dry) P *= 0.3;
if (P < 0) P = 0;
let W = nRun > 0 ? (flowIn * P / 600) / 0.6 + 0.3 * nRun : 0.05;   // kW hidraulico / rendimiento 0.6
if (dry) W *= 0.6;

// ---------- Guardar estado ----------
s.volume = vol; s.level = level;
s.flowIn = flowIn; s.flowOut = flowOut; s.demand = outD; s.leak = outL;
s.pressure = P; s.power = W; s.dry = dry;
S('b02_state', s);

msg.payload = {
  ts: now, iso: new Date(now).toISOString(), dt: dt,
  level: level, volume: vol, flowIn: flowIn, flowOut: flowOut, demand: outD, leak: outL,
  pressure: P, power: W, setpoint: s.setpoint, nRun: nRun, dry: dry,
  run: { 1: s.pumps[1].run, 2: s.pumps[2].run }
};
node.status({ fill: 'green', shape: 'dot', text: 'Nivel ' + level.toFixed(1) + '% | bombas: ' + nRun });
return msg;

// ---- Utilidades comunes: contexto GLOBAL file-backed (con respaldo en memoria) ----
const ST = 'file';
const G = k => { try { return global.get(k, ST); } catch (e) { return global.get(k); } };
const S = (k, v) => { try { global.set(k, v, ST); } catch (e) { global.set(k, v); } };
const R = (x, n) => { const f = Math.pow(10, n || 0); return Math.round(x * f) / f; };

// APLICAR PERTURBACION
// Llega desde los inject manuales o desde la API (POST /api/B02/disturbance).
const s = G('b02_state');
if (!s) return null;
const p = msg.payload || {};
const type = (typeof p === 'string') ? p : p.type;
const recuperar = () => {
  s.demandFactor = 1; s.leakLpm = 0; s.valveClosed = false;
  [1, 2].forEach(i => { s.pumps[i].fault = false; s.pumps[i].enabled = true; });
  s.setpoint = 65;
};
let txt = '';
switch (type) {
  case 'CONSUMPTION_UP': s.demandFactor = 2.2; txt = 'Aumento de consumo (x2.2)'; break;
  case 'LEAK': s.leakLpm = 100; txt = 'Fuga en el tanque (100 L/min a nivel lleno)'; break;
  case 'PUMP_FAULT': {
    const id = (p.pumpId === 1 || p.pumpId === 2) ? p.pumpId : s.main;
    s.pumps[id].fault = true; s.pumps[id].run = false;
    txt = 'Averia de la bomba ' + id; break;
  }
  case 'VALVE_CLOSED': s.valveClosed = true; txt = 'Valvula de salida casi cerrada (consumo x0.1)'; break;
  case 'SEVERE':
    s.demandFactor = 2.5; s.leakLpm = 150; s.volume = Math.min(s.volume, 500);
    s.pumps[s.main].fault = true; s.pumps[s.main].run = false;
    txt = 'Falla grave: fuga + consumo alto + bomba principal averiada'; break;
  case 'RECOVER': recuperar(); txt = 'Recuperacion: fallas eliminadas, bombas habilitadas, SP=65%'; break;
  case 'NORMAL_FILL': recuperar(); s.volume = 600; s.level = 30; txt = 'Llenado normal: tanque al 30%, condiciones normales'; break;
  default: node.warn('Perturbacion desconocida: ' + type); return null;
}
S('b02_state', s);
node.status({ fill: 'yellow', shape: 'dot', text: txt });
msg.payload = txt;
return msg;

