// POST /api/B02/commands   { "command": "START_PUMP" | "STOP_PUMP" | "TOGGLE_MAIN", "pumpId": 1 | 2 }
msg._t0 = Date.now();
msg._ep = 'POST /api/B02/commands';
const respond = (code, obj) => {
  msg.statusCode = code;
  msg._detalle = obj.error || obj.mensaje || '';
  msg.payload = Object.assign({ timestamp: new Date().toISOString(), ok: code === 200 }, obj);
  return msg;
};
const b = msg.payload;
if (!b || typeof b !== 'object' || Array.isArray(b)) return respond(400, { error: 'El cuerpo debe ser un JSON con command y pumpId' });
const cmd = b.command, id = b.pumpId;
const permitidos = ['START_PUMP', 'STOP_PUMP', 'TOGGLE_MAIN'];
if (!permitidos.includes(cmd)) return respond(400, { error: 'Comando invalido', permitidos: permitidos });
const idOk = (id === 1 || id === 2);
if (cmd !== 'TOGGLE_MAIN' && !idOk) return respond(400, { error: 'pumpId debe ser 1 o 2' });
if (cmd === 'TOGGLE_MAIN' && id !== undefined && !idOk) return respond(400, { error: 'pumpId debe ser 1 o 2' });
const s = G('b02_state');
if (!s) return respond(503, { error: 'Simulador no inicializado' });

if (cmd === 'START_PUMP') {
  const p = s.pumps[id];
  if (p.fault) return respond(409, { error: 'No se puede arrancar la bomba ' + id + ': esta averiada' });
  if (p.enabled) return respond(409, { error: 'La bomba ' + id + ' ya esta habilitada' });
  p.enabled = true;
  S('b02_state', s);
  return respond(200, { command: cmd, pumpId: id, mensaje: 'Bomba ' + id + ' habilitada (el control automatico la arranca segun el nivel)' });
}
if (cmd === 'STOP_PUMP') {
  const p = s.pumps[id];
  if (!p.enabled) return respond(409, { error: 'La bomba ' + id + ' ya esta detenida' });
  p.enabled = false; p.run = false;
  S('b02_state', s);
  return respond(200, { command: cmd, pumpId: id, mensaje: 'Bomba ' + id + ' detenida' });
}
// TOGGLE_MAIN
const destino = idOk ? id : (s.main === 1 ? 2 : 1);
if (destino === s.main) return respond(409, { error: 'La bomba ' + destino + ' ya es la principal' });
if (s.pumps[destino].fault) return respond(409, { error: 'No se puede hacer principal la bomba ' + destino + ': esta averiada' });
s.main = destino;
S('b02_state', s);
return respond(200, { command: cmd, pumpId: destino, mensaje: 'La bomba principal ahora es la ' + destino });

