const raw = b.setpoint;
const v = (typeof raw === 'number') ? raw : ((typeof raw === 'string' && raw.trim() !== '') ? Number(raw) : NaN);
if (!isFinite(v)) return respond(400, { error: 'setpoint debe ser un numero' });
if (v < 0 || v > 100) return respond(400, { error: 'setpoint fuera de rango: debe estar entre 0 y 100', recibido: v });
const s = G('b02_state');
if (!s) return respond(503, { error: 'Simulador no inicializado' });
s.setpoint = v;
S('b02_state', s);
return respond(200, { setpoint_pct: v, mensaje: 'Nivel objetivo actualizado a ' + v + '%' });

