const al = G('b02_alarms') || [];
const ahora = new Date().toISOString();
let n = 0;
if (b.all === true) {
  al.forEach(a => { if (!a.reconocida) { a.reconocida = true; a.tsReconocida = ahora; n++; } });
} else if (typeof b.id === 'string') {
  const a = al.find(x => x.id === b.id);
  if (!a) return respond(404, { error: 'Alarma no encontrada', id: b.id });
  if (!a.reconocida) { a.reconocida = true; a.tsReconocida = ahora; n = 1; }
} else {
  return respond(400, { error: 'Falta id (texto) o all:true' });
}
S('b02_alarms', al);
return respond(200, { reconocidas: n, mensaje: n + ' alarma(s) reconocida(s)' });

